1	import { precompile } from '../../components/effects/shaderWarmup.ts';
2	import React, { useEffect, useMemo, useRef } from 'react';
3	import { useFrame } from '@react-three/fiber';
4	import { CuboidCollider, RigidBody } from '@react-three/rapier';
5	import * as THREE from 'three';
6	import { voxelSystem } from '../../utils/efficientVoxelSystem.ts';
7	import { VOXEL_SCALE } from '../../utils/cubeGravityConstants.ts';
8	import { createLiveAgentSurfaceTerrain } from '../../utils/agentSurfaceNavigationRuntime.ts';
9	import { heroTreeHandle } from './HeroAppleTree.tsx';
10	import {
11	  CG_APPARATUS_SOLIDS,
12	  type CommonGroundAabb,
13	  type CommonGroundFooting
14	} from '../commonGroundRoute.ts';
15	import {
16	  MAX_TRACE_POINTS,
17	  readCommonGroundLive,
18	  type CommonGroundPoint
19	} from '../commonGroundState.ts';
20	import { registerCommonGroundWorld } from '../commonGroundDirector.ts';
21	import { restoreCommonGroundForWorld } from '../../game/systems/persistence.ts';
22	
23	// --- The survey apparatus and the drawn trace ----------------------------------------
24	//
25	// The apparatus is four boxes and the trace is up to 512 pooled glyphs, and both
26	// are single instanced meshes sharing one material each. That is the INTENDED
27	// shape against the accepted +8 draw / +6 material / +6 program / +2 MiB budget;
28	// it is a design claim, not a measurement, and no render or resource budget is
29	// claimed as verified here — an independent capture owns that.
30	//
31	// NO NEW LIGHT. Light cardinality is fixed at the shipped count; the instrument
32	// reads by its own silhouette against the ground, which is also why it must be
33	// legible at POTATO with no effect at all.
34	//
35	// Everything is allocated and precompiled at MOUNT, before any critical verb:
36	// the ±2 second window around the offer, the start, the span offer, the hold,
37	// the revision and the completion must contain zero first-use of a program or a
38	// resource, and there are no frame-loop allocations below.
39	
40	/** The body's grounded clearance above its support surface, as qualified. */
41	const GROUND_CLEARANCE = 1.05;
42	/** Pooled trace glyphs: two route slots of at most 128 points each, ×2 spare. */
43	const TRACE_GLYPH_POOL = 512;
44	
45	const APPARATUS_COLOR = '#8d9a95';
46	const APPARATUS_DARK = '#55605d';
47	/** The trace reads as her own line: the shipped ember, not a new accent. */
48	const TRACE_COLOR = '#ff5a3c';
49	
50	function cell(value: number): number {
51	  return Math.round(value / VOXEL_SCALE);
52	}
53	
54	/**
55	 * Live footing over the actual voxel world.
56	 *
57	 * The support column is the cell whose top face the body stands on
58	 * (`y - 1.05`), the cell above it must be empty, and neither may be water. The
59	 * body disc is sampled at its centre and at four lateral offsets, so a foot
60	 * half over a hole is not "supported" merely because its centre is.
61	 */
62	function createFooting(planetSize: number, terrainSeed: number, worldId: string): CommonGroundFooting {
63	  const terrain = createLiveAgentSurfaceTerrain(planetSize, terrainSeed, worldId);
64	  const supportedColumn = (x: number, y: number, z: number): boolean => {
65	    const cx = cell(x);
66	    const cz = cell(z);
67	    const cy = cell(y - GROUND_CLEARANCE);
68	    if (!terrain.isSolidVoxel(cx, cy, cz)) return false;
69	    if (terrain.isSolidVoxel(cx, cy + 1, cz)) return false;
70	    if (terrain.isWaterVoxel(cx, cy, cz) || terrain.isWaterVoxel(cx, cy + 1, cz)) return false;
71	    if (terrain.isHazardousVoxel?.(cx, cy, cz)) return false;
72	    return true;
73	  };
74	  return {
75	    // LIVE, NOT CAPTURED. `createLiveAgentSurfaceTerrain` builds its revision
76	    // string once, so copying it would pin the value at mount and every later
77	    // edit would look like no edit at all. The predicates below already read the
78	    // voxel system live; this makes the invalidation token agree with them.
79	    get revision(): string {
80	      return `${voxelSystem.getWorldId()}:${voxelSystem.getEditVersion()}`;
81	    },
82	    isSupported: (point: CommonGroundPoint) => supportedColumn(point.x, point.y, point.z)
83	      && supportedColumn(point.x + 0.5, point.y, point.z)
84	      && supportedColumn(point.x - 0.5, point.y, point.z)
85	      && supportedColumn(point.x, point.y, point.z + 0.5)
86	      && supportedColumn(point.x, point.y, point.z - 0.5)
87	  };
88	}
89	
90	/** The hero tree's EXISTING trunk collider, included in the route guard. */
91	function trunkSolid(): CommonGroundAabb | null {
92	  const position = heroTreeHandle.position;
93	  if (!position) return null;
94	  const height = Math.max(1, heroTreeHandle.height ?? 7.2);
95	  return {
96	    name: 'hero-tree-trunk',
97	    lo: { x: position.x - 0.55, y: position.y, z: position.z - 0.55 },
98	    hi: { x: position.x + 0.55, y: position.y + height, z: position.z + 0.55 }
99	  };
100	}
101	
102	const _matrix = new THREE.Matrix4();
103	const _position = new THREE.Vector3();
104	const _quaternion = new THREE.Quaternion();
105	const _scale = new THREE.Vector3();
106	
107	const CommonGroundWorld: React.FC<{
108	  planetSize: number;
109	  terrainSeed: number;
110	  worldId: string;
111	  /** True only while a ch13 beat owns the frame; the sandbox never mounts this. */
112	  active: boolean;
113	}> = ({ planetSize, terrainSeed, worldId, active }) => {
114	  const groupRef = useRef<THREE.Group>(null);
115	  const apparatusRef = useRef<THREE.InstancedMesh>(null);
116	  const traceRef = useRef<THREE.InstancedMesh>(null);
117	
118	  const materials = useMemo(() => ({
119	    housing: new THREE.MeshStandardMaterial({ color: APPARATUS_COLOR, roughness: 0.8, metalness: 0.1 }),
120	    trace: new THREE.MeshStandardMaterial({
121	      color: TRACE_COLOR,
122	      roughness: 0.9,
123	      emissive: new THREE.Color(TRACE_COLOR),
124	      emissiveIntensity: 0.35
125	    })
126	  }), []);
127	  useEffect(() => () => {
128	    materials.housing.dispose();
129	    materials.trace.dispose();
130	  }, [materials]);
131	
132	  // The apparatus never moves, so its instance matrices are written once, at
133	  // mount, and the buffer is then static for the whole chapter.
134	  useEffect(() => {
135	    const mesh = apparatusRef.current;
136	    if (!mesh) return;
137	    CG_APPARATUS_SOLIDS.forEach((box, index) => {
138	      _position.set((box.lo.x + box.hi.x) / 2, (box.lo.y + box.hi.y) / 2, (box.lo.z + box.hi.z) / 2);
139	      _scale.set(box.hi.x - box.lo.x, box.hi.y - box.lo.y, box.hi.z - box.lo.z);
140	      _quaternion.identity();
141	      mesh.setMatrixAt(index, _matrix.compose(_position, _quaternion, _scale));
142	    });
143	    mesh.count = CG_APPARATUS_SOLIDS.length;
144	    mesh.instanceMatrix.needsUpdate = true;
145	    mesh.frustumCulled = false;
146	  }, []);
147	
148	  // PREWARM. Compile both programs and upload both buffers at mount, so the
149	  // first offered span cannot be the frame that compiles a shader.
150	  useEffect(() => {
151	    const root = groupRef.current;
152	    if (root) return precompile(root);
153	  }, []);
154	
155	  // This world's saved chapter state, staged for the director to validate. The
156	  // same reset-then-load shape every other per-world field uses.
157	  useEffect(() => {
158	    if (!worldId) return;
159	    restoreCommonGroundForWorld({ worldId, seed: terrainSeed });
160	  }, [terrainSeed, worldId]);
161	
162	  useEffect(() => {
163	    // READINESS GATES THE QUERIES. Binding before this world's voxels are the
164	    // resident ones would answer route questions about somebody else's ground.
165	    if (!active || !worldId) return;
166	    const footing = createFooting(planetSize, terrainSeed, worldId);
167	    const trunk = trunkSolid();
168	    return registerCommonGroundWorld({
169	      worldId,
170	      footing,
171	      extraSolids: trunk ? [trunk] : []
172	    });
173	  }, [active, planetSize, terrainSeed, worldId]);
174	
175	  useFrame(() => {
176	    const mesh = traceRef.current;
177	    if (!mesh) return;
178	    const snapshot = active ? readCommonGroundLive(worldId) : null;
179	    // The proposal being drawn, or the accepted route once one is retained.
180	    const samples = (snapshot?.survey.working ?? snapshot?.survey.accepted)?.samples ?? null;
181	    if (!samples || samples.length === 0) {
182	      if (mesh.count !== 0) {
183	        mesh.count = 0;
184	        mesh.instanceMatrix.needsUpdate = true;
185	      }
186	      return;
187	    }
188	    // Bounded by construction: the slot itself cannot exceed the sample cap, and
189	    // the pool holds two such slots twice over. Capacity stops honestly upstream;
190	    // nothing is decimated to fit here either.
191	    const count = Math.min(samples.length, MAX_TRACE_POINTS, TRACE_GLYPH_POOL);
192	    for (let index = 0; index < count; index += 1) {
193	      const sample = samples[index];
194	      _position.set(sample.x, sample.y + 0.06, sample.z);
195	      _quaternion.identity();
196	      // A corner reads slightly larger: the trace records where she turned, and
197	      // that is a fact about the argument rather than decoration.
198	      const size = sample.corner ? 0.34 : 0.22;
199	      _scale.set(size, 0.06, size);
200	      mesh.setMatrixAt(index, _matrix.compose(_position, _quaternion, _scale));
201	    }
202	    mesh.count = count;
203	    mesh.instanceMatrix.needsUpdate = true;
204	    mesh.frustumCulled = false;
205	  });
206	
207	  return (
208	    <group ref={groupRef}>
209	      {/*
210	        REAL COLLIDERS, not just a walk-mask entry. The route guard stops the
211	        chapter from PLANNING through the housing; it cannot stop the player's
212	        live body walking through a thing they can see. The same literal AABBs
213	        are registered as fixed colliders, the way the hero tree's trunk already
214	        is: the instrument is real, and you cannot walk through the argument.
215	      */}
216	      {active && (
217	        <RigidBody type="fixed" colliders={false}>
218	          {CG_APPARATUS_SOLIDS.map(box => (
219	            <CuboidCollider
220	              key={box.name}
221	              args={[
222	                (box.hi.x - box.lo.x) / 2,
223	                (box.hi.y - box.lo.y) / 2,
224	                (box.hi.z - box.lo.z) / 2
225	              ]}
226	              position={[
227	                (box.lo.x + box.hi.x) / 2,
228	                (box.lo.y + box.hi.y) / 2,
229	                (box.lo.z + box.hi.z) / 2
230	              ]}
231	            />
232	          ))}
233	        </RigidBody>
234	      )}
235	      <instancedMesh
236	        ref={apparatusRef}
237	        args={[undefined, undefined, CG_APPARATUS_SOLIDS.length]}
238	        material={materials.housing}
239	        castShadow={false}
240	        receiveShadow={false}
241	      >
242	        <boxGeometry args={[1, 1, 1]} />
243	      </instancedMesh>
244	      <instancedMesh
245	        ref={traceRef}
246	        args={[undefined, undefined, TRACE_GLYPH_POOL]}
247	        material={materials.trace}
248	        castShadow={false}
249	        receiveShadow={false}
250	      >
251	        <boxGeometry args={[1, 1, 1]} />
252	      </instancedMesh>
253	    </group>
254	  );
255	};
256	
257	export default CommonGroundWorld;
258	export { APPARATUS_DARK, createFooting, trunkSolid, TRACE_GLYPH_POOL };

