import { createLiveAgentSurfaceTerrain } from '../../utils/agentSurfaceNavigationRuntime.ts';
import { heroTreeHandle } from './HeroAppleTree.tsx';
import {
  CG_APPARATUS_SOLIDS,
  type CommonGroundAabb,
  type CommonGroundFooting
} from '../commonGroundRoute.ts';
