332	/**
333	 * Bank actual body displacement against the length cap.
334	 *
335	 * Called with the real distance the body moved this frame, whether or not a
336	 * sample is recorded for it. A pause, a focus loss or a resume neither loses
337	 * nor invents this debt; it is simply distance she walked.
338	 */
339	export function accumulateTraceDistance(slot: TraceSlot, displacement: number): void {
340	  if (!(displacement > 0) || slot.atCapacity) return;
341	  const next = slot.walkedUnits + displacement;
342	  if (next > MAX_TRACE_LENGTH_UNITS) {
343	    slot.walkedUnits = MAX_TRACE_LENGTH_UNITS;
344	    slot.pendingUnits = MAX_TRACE_LENGTH_UNITS - slot.samples[slot.samples.length - 1].walkedAt;
