820-  const slot = snapshot.survey.working;
821-  if (!slot) return;
822-  slot.routeClass = routeClass;
823-  markTestedPrefix(slot, slot.samples.length);
824-  snapshot.survey.accepted = slot;
825-  snapshot.survey.working = null;
826-  snapshot.survey.phase = 'tested';
827-}
828-
829-/** Presentation ownership only: what a pause or a world departure may drop. */
830-export function releaseLiveOccupancy(snapshot: CommonGroundSnapshot): void {
831-  if (snapshot.survey.witness) snapshot.survey.witness.occupied = false;
832-  snapshot.common.finalReferenceOccupied = false;
833-}
